const Compliance = { EU: 2, US: 4 }; // values from contracts/utils/CommonUtils.sol
const FRANCE = 'france';
const USA = 'usa';
const FRENCH_INVESTOR_ID = 'frenchInvestorId';
const US_INVESTOR_ID = 'usInvestorId';

async function deployDSTokenRegulated() {
