        vm.expectRevert();
        timelock.grantRole(PROPOSER_ROLE, alice);

        vm.prank(deployer);
        vm.expectRevert();
        timelock.grantRole(PROPOSER_ROLE, alice);

        vm.prank(address(timelock));
        vm.expectRevert();
        timelock.grantRole(PROPOSER_ROLE, alice);

