        address _pool,
        address _swapper,
        address _debtAsset,
        address _yieldAsset,
        uint256 _initialAmount,
        uint256 _flashloanAmount,
        uint256 _minAmountOut,
        address[] memory _path,
        bool _startWithYield,
+       uint256 _minInitialAmountOut
