        bytes32 EIP712_DOMAIN_TYPEHASH = keccak256("EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)");
        bytes32 nameHash = keccak256("PaymentRouter");
        bytes32 versionHash = keccak256("1");
        uint256 chainId = block.chainid;
        address verifyingContract = address(router);

        bytes32 domainSeparator = keccak256(abi.encode(
            EIP712_DOMAIN_TYPEHASH,
            nameHash,
            versionHash,
            chainId,
            verifyingContract
        ));

        return keccak256(abi.encodePacked(
            "\x19\x01",
            domainSeparator,
            structHash
        ));
    }

    function test_Exploit_DuplicateOrderIdsInBatch() public {
        uint256[] memory ids = new uint256[](2);
        ids[0] = 777;
        ids[1] = 777; // Duplicate ID!

        uint256[] memory amounts = new uint256[](2);
        amounts[0] = 10 * 1e6;
        amounts[1] = 10 * 1e6;

        uint256 validUntil = block.timestamp + 1 hours;

        // Backend signs the batch (assuming backend checks are also loose or bypassed,
        // OR simply demonstrating that the contract doesn't enforce uniqueness)
        bytes memory sig = _signBatch(backendPk, ids, amounts, validUntil, user, treasury);

        uint256 initialTreasuryBalance = usdc.balanceOf(treasury);

        vm.prank(user);
        router.payOrdersBatch(ids, amounts, validUntil, sig);

        // Verification:
        // Treasury should have received 20 USDC
        assertEq(usdc.balanceOf(treasury), initialTreasuryBalance + 20 * 1e6);

        // Order 777 is processed
        assertTrue(router.processedOrders(777));
    }
}
```

## Recommendation

Update the `processedOrders` state in the first loop so subsequent iterations detect the duplicate.

```diff
// Loop to validate logic and sum total
for (uint256 i = 0; i < len; i++) {
+   if (processedOrders[orderIds[i]]) revert OrderAlreadyProcessed();
+   processedOrders[orderIds[i]] = true;
    _validateOrderLogic(orderIds[i], amounts[i]);
    totalAmount += amounts[i];
}
```

## Team Response

Fixed.

## [I-01] Batch Safety Cap Check Is Redundant and Can Overflow, Bricking Batch Payments

## Severity

Informational Risk

## Description

`PaymentRouter.payOrdersBatch(...)` allows users to pay up to 50 orders in one call and enforces a per-order limit via `maxPaymentAmount`. However, after summing the amounts, it performs an additional batch-level check using `maxPaymentAmount * 50`. Because Solidity 0.8+ reverts on arithmetic overflow, if `maxPaymentAmount` is configured above `type(uint256).max / 50`, then `maxPaymentAmount * 50` will revert, causing all batch payments to fail until the limit is reduced. This is primarily an operational risk because `maxPaymentAmount` is set by `MANAGER_ROLE`.

## Location of Affected Code

File: `src/PaymentRouter.sol`

```solidity
function payOrdersBatch(
    uint256[] calldata orderIds,
    uint256[] calldata amounts,
    uint256 validUntil,
    bytes calldata signature
) external nonReentrant whenNotPaused {
    // code
    for (uint256 i = 0; i < len; i++) {
        _validateOrderLogic(orderIds[i], amounts[i]);
        totalAmount += amounts[i];
    }

    // @audit Redundant multiplication that can overflow and revert
    if (totalAmount > maxPaymentAmount * 50) revert AmountTooLarge();
    // code
}
```

## Impact

A misconfiguration can make `payOrdersBatch(...)` revert for all users until `maxPaymentAmount` is set back to a safe value, causing operational DoS for batch payments. Additionally, the batch check does not add protection beyond `len <= 50` and the per-item check `amounts[i] <= maxPaymentAmount`, meaning it provides no additional safety benefit.

## Recommendation

Remove the redundant check, since each order is already validated to be `<= maxPaymentAmount` and the batch length is capped at 50, the batch-level check is redundant and can be safely removed:

```diff
--- a/src/PaymentRouter.sol
+++ b/src/PaymentRouter.sol

@@ -125,8 +125,6 @@ contract PaymentRouter is ReentrancyGuard, Pausable, AccessControl, EIP712 {
     for (uint256 i = 0; i < len; i++) {
         _validateOrderLogic(orderIds[i], amounts[i]);
         totalAmount += amounts[i];
     }
-
-    if (totalAmount > maxPaymentAmount * 50) revert AmountTooLarge();

     // Verify Signature (Batch Hash)
     bytes32 batchHash = keccak256(abi.encode(orderIds, amounts));
```

## Team Response

Fixed.

## Diﬃculty: Low

## Type: Error Reporting

## Description
The `getMaxLiquidityForAmount0Precise` function can overflow because multiplication is performed before division, potentially leading to a loss of jettons when a user attempts to mint liquidity through the maximum liquidity path.

The `computeLiquidity` function is used to calculate the maximum amount of liquidity that a user can mint using the jetton amounts they transferred; specifically, the function is used when a user passes the `MINT_AS_MUCH_AS_POSSIBLE` operation to the `mintPosition` function. The `computeLiquidity` function calls the `getMaxLiquidityForAmounts` function to perform the calculation. If the current square root price is within or below the tick bounds of the position, `getMaxLiquidityForAmounts` will call `getMaxLiquidityForAmount0Precise`:

```solidity
int getMaxLiquidityForAmount0Precise(int sqrtRatioAX96, int sqrtRatioBX96, int amount0) {
    if (sqrtRatioAX96 > sqrtRatioBX96) {
        [sqrtRatioAX96, sqrtRatioBX96] = [sqrtRatioBX96, sqrtRatioAX96];
    }
    int numerator = (amount0 * sqrtRatioAX96) * sqrtRatioBX96;
    int denominator = Q96 * (sqrtRatioBX96 - sqrtRatioAX96);
    return numerator / denominator;
}
```
*Figure 22.1: The overflow in `getMaxLiquidityForAmount0Precise` (contracts/pool/amounts.func#L31–L40)*

However, on the highlighted line of figure 22.1, we can see that three potentially large values are multiplied at once. This calculation can easily overflow the 257-bit signed integer when the amount or prices are large, causing the message to fail and the jettons to be lost.

## Exploit Scenario
Alice attempts to deposit jettons into a pool between two large ticks using the maximum liquidity path. Her transaction fails due to an overflow in the `getMaxLiquidityForAmount0Precise` function and she permanently loses her jettons.

## Recommendations
- **Short term**: Use the same approach used in Uniswap v3: calculate an intermediate value first before the final value in order to avoid overflows in the multiplication step. Use `muldiv` to take advantage of the 513-bit precision.

- **Long term**: Use stateless fuzzing to test all of the calculations performed in the protocol for overflow risks.

## Severity

Medium Risk

## Description

When a pawn expires, `PawnShop.liquidate(...)` closes the position by burning the escrowed NFT collateral through the NFT’s `burn(...)` function (context).

However, in this system, the NFT is `RWA`, whose burn path is gated by `whenNotPaused`, and whose transfer/burn internals revert if the caller (`auth`) is blacklisted. This means an admin action on `RWA` (pause or blacklist) can cause `PawnShop.liquidate(...)` to revert (problem).

This traps the loan in an unrecoverable state: the borrower cannot redeem after the `deadline`, and the manager cannot liquidate, so the collateral remains stuck in `PawnShop` indefinitely (impact).

## Location of Affected Code

File: [Pawn.sol#L262-L271](https://github.com/ShinyUrban/SmartContracts/blob/f49b5db73b297552666783ed587cf0818ef86b75/Pawn.sol#L262-L271)

```solidity
function liquidate(uint256 tokenId) external nonReentrant whenNotPaused onlyRole(MANAGER_ROLE) {
    Pawn memory pawning = pawns[tokenId];
    if (!pawning.active) revert TokenNotPawned();
    if (block.timestamp < pawning.deadline) revert DeadlineNotPassed();

    pawns[tokenId].active = false;

    // @audit Depends on external NFT burn rules
    IERC721Burnable(address(nftToken)).burn(tokenId);
}
```

File: [sRWA.sol#L189-L197](https://github.com/ShinyUrban/SmartContracts/blob/f49b5db73b297552666783ed587cf0818ef86b75/sRWA.sol#L189-L197)

```solidity
function burn(uint256 tokenId) external onlyTokenOwner(tokenId) whenNotPaused {
    // code
    _burn(tokenId);
}
```

File: [sRWA.sol#L270-L277](https://github.com/ShinyUrban/SmartContracts/blob/f49b5db73b297552666783ed587cf0818ef86b75/sRWA.sol#L270-L277)

```solidity
function _update(address to, uint256 tokenId, address auth) internal virtual override returns (address) {
    // code
    if (auth != address(0) && _isBlacklisted[auth]) revert Blacklisted();
    // code
}
```

## Impact

- Expired loans may become impossible to close if `RWA` is paused or if `PawnShop` is blacklisted.
- Borrowers cannot redeem after `deadline`, so collateral can remain trapped without a clean resolution path.

## Proof of Concept

1. User opens a pawn via `PawnShop.pawn(...)`.
2. Time passes beyond `deadline`.
3. Admin pauses `RWA` (or blacklists `PawnShop` in `RWA`).
4. Manager calls `PawnShop.liquidate(tokenId)`.
5. The call reverts when it reaches `RWA.burn(...)`, leaving the loan stuck.

## Recommendation

- **Decouple liquidation from `RWA` pause/blacklist**:
  - Allow `PawnShop` to liquidate by transferring the NFT to a protocol-controlled address if burning is blocked, or
  - Give `PawnShop` a special role in `RWA` that can burn even when paused / not subject to blacklist, or
  - Modify `RWA` so that pausing does not block burns initiated by the protocol liquidator.
- Consider allowing **borrower redemption at/after deadline until liquidation occurs** to avoid “stuck forever” states.

