        marketData[0] = abi.encode(marketParams_1);
        amounts[0] = 100e18;

        vm.prank(bob);
        vault.forceDeallocate(adapters, marketData, amounts, bob);

        vm.prank(bob);
        vault.redeem(100e18, bob, bob);

        // assert that BOB was able to withdraw what he had deposited
