-           uint256 minAmountOut = (((_flashloanAmount * 1e8) / _minAmountOut) *
-               _initialAmount) / 1e8;

+           uint256 minAmountOut = (((_flashloanAmount * 1e36) / _minAmountOut) *
+               _initialAmount) / 1e36;

