   function init(
       DataTypes.MiniPoolReserveData storage reserve,
       address asset,
       IAERC6909 aTokenAddress,
       uint256 aTokenID,
       uint256 variableDebtTokenID,
       address interestRateStrategyAddress
   ) internal {
