    // ... execute swap ...

    uint256 postSwapBalance = stablecoinBalance();
    uint256 amountReceived = postSwapBalance - preSwapBalance;

    if (amountReceived < minAmountOut) {
        revert GeniusErrors.InvalidAmountOut(amountReceived, minAmountOut);
    }
}
