102:         );
103:         poolToken.transferFrom(msg.sender, address(this), amount);
104:         uint shareChange = totalLiquidity > 0
105:             ? (depositShare * amount) / totalLiquidity
106:             : (amount * 10 ** decimals()) / 10 ** poolToken.decimals
(...)
