modifier validStakePeriodParams(uint key, uint startTime, uint endTime, uint rewardPool) {
    require(startTime <= block.timestamp,                   "STAKE_TOKEN: invalid_start");
    require(startTime < endTime,                            "STAKE_TOKEN: invalid_time");
