    psm.approve(address(portal_USDC), 1e55);
    uint256 balPsmBefore = psm.balanceOf(Alice);
    portal_USDC.buyPortalEnergy(Alice, balPsmBefore, 1, block.timestamp);
    uint256 psmSpent = balPsmBefore - psm.balanceOf(Alice);
