    portal_USDC.sellPortalEnergy(Alice, result, 1, block.timestamp);
    // extracted value :
    uint256 valueExtracted = psm.balanceOf(Alice) - balPsmBefore;
    console2.log("value spend %e", psmSpent);
    console2.log("value extracted %e", valueExtracted);
