            _updateMarketRewards(_rewardInfoByToken[_rewardToken].marketAddresses[i]);
            unchecked {
                ++i; // saves 63 gas per iteration
            }
++          delete _marketWeightsByToken[_rewardToken][_rewardInfoByToken[_rewardToken].marketAddresses[i]];
