        string memory _baseUri,
        address _usdc
    ) external;
}

contract ThreeDNSTest is Test {
    string constant OPT_RPC = "https://rpc.ankr.com/optimism";
    IThreeDNSRegControl template = IThreeDNSRegControl(0xcE8Af21eFeC523183D4AD6B7123E18c981848245);
