function \_calculateY(
 bytes calldata \_data,
 bytes32 \_compressedDataComputedX
) internal pure returns (bytes32 compressedDataComputedY) {
 if (\_data.length % 0x20 != 0) {
 revert BytesLengthNotMultipleOf32();
