  bytes32 loanId = _setupAndCallLoan();
  uint256 PHASE_1_DURATION = auctionHouse.midPoint();
  uint256 PHASE_2_DURATION = auctionHouse.auctionDuration() - auctionHouse.midPoint();
  vm.roll(block.number + 1);
