    contract FakeBasicActions {
       using Math for uint256;

      function lockTokenCollateralAndGenerateDebt(
        address _manager,
        address _taxCollector,
        address _collateralJoin,
        address _coinJoin,
        uint256 _safeId,
        uint256 _collateralAmount,
        uint256 _deltaWad
