          tickActiveEnd = tickTracking.exitTimestamp;
          tickTrackingIndex++;
          dt = tickActiveEnd - tickActiveStart;
       } else {
         // Exit was in next week, we need to consider the current tick there (i.e. not increase the index)
         tickActiveEnd = nextWeek;
        }
