    forkingPeriodEndTimestamp = forkingPeriodEndTimestamp_;
}
```

```solidity
// NounsDAOLogicV1Fork.sol#L107
error WaitingForTokensToClaimOrExpiration();
error WaitingForForkPeriodEnd();
```

```solidity
