43:         int128 i = -1;
44:         int128 j = -1;
45:         for (int128 c = 0; c < MAX_TOKENS; c++) {
46:             address coin = pool.coins(uint256(int256(c)));
47:             if (coin == sellToken) i = c;
48:             if (coin == buyToken) j = c;
49:             if (i > -1 && j > -1) break;
