 GEODE.GOVERNANCE = \_GOVERNANCE;
 GEODE.GOVERNANCE\_TAX = \_GOVERNANCE\_TAX;
 GEODE.MAX\_GOVERNANCE\_TAX = \_GOVERNANCE\_TAX;
 GEODE.SENATE\_EXPIRY = type(uint256).max;

 STAKEPOOL.GOVERNANCE = \_GOVERNANCE;
 STAKEPOOL.gETH = IgETH(\_gETH);
 STAKEPOOL.TELESCOPE.gETH = IgETH(\_gETH);
 STAKEPOOL.TELESCOPE.ORACLE\_POSITION = \_ORACLE\_POSITION;
 STAKEPOOL.TELESCOPE.MONOPOLY\_THRESHOLD = 20000;

