  if( isSwapEnabled ) {
    revert Aera__PoolSwapIsAlreadyEnabled();
  }
  uint256 timestamp = block.timestamp;
  pool.updateWeightsGradually(timestamp, timestamp, weights);
  setSwapEnabled(true);
}
```

