@@ -218,6 +218,7 @@ contract Lend is ReentrancyGuard {
    payable(msg.sender).transfer(2 * payoutPerResCurrent / 100);
    emit BorrowerLiquidated(openLoan.borrower, _pool, nft, id, loanAmount);
+   delete loanDeployed[nft][id];
    delete loans[nft][id];
}
```

