function redeemZero(...) external nonReentrant whenNotPaused returns (uint256 tBal) {
    ...
    if (level.redeemZeroRestricted()) {
        require(msg.sender == adapter, Errors.RedeemZeroRestricted);
    }
}
```

## Recommendation
Double check if calling from `Periphery` should also be allowed.

## Sense
After seeing this issue, we’ve decided that if `redeemZeroRestricted()` in `Divider.sol` (Lines 289-291) is set, then when `_removeLiquidity()` in `Periphery.sol` (Lines 551-578) is called at or after maturity, we will not be redeeming zeros and will transfer the zeros back to the user. You can see this change on PR#160.

## Spearbit
Acknowledged.

## Security Vulnerability Report

## Severity
**Medium Risk**

## Context
**File**: GClaimManager.sol  
**Lines**: 77-104

## Situation
In the function `exit()` of `GClaimManager.sol`, the burning of the tokens is done at the end. This does not conform to the Checks-Effects-Interactions pattern, and no non-Reentrant modifier is employed. Therefore, reentrancy is possible with a malicious adapter contract, and there are potential risks in other situations as well.

Here is an excerpt of the relevant code:

```solidity
function exit(address adapter, uint48 maturity, uint256 uBal) external {
    // External call
    uint256 collected = Claim(claim).collect();

    // External call
    uint256 tBal = uBal.fdiv(gclaims[claim].totalSupply(), total);

    // External call
    ERC20(Adapter(adapter).target()).safeTransfer(msg.sender, tBal);

    // External call
    ERC20(claim).safeTransfer(msg.sender, uBal);

    // Burn the user's gclaims
    // Completed at the very end with potential reentrancy above
    gclaims[claim].burn(msg.sender, uBal);
}
```

## Recommendation
To improve security, add a `nonReentrant` modifier on functions of `GClaimManager` that perform external calls.

## Note
`GClaimManager` will most likely be deprecated. This issue is included for completeness.

## Severity: Medium Risk

## Context
- GClaimManager.sol
- Claim.sol
- Divider.sol

## Situation
When calling the function `join()` and `exit()` from contract `GClaimManager`, the function `_collect()` of `Divider` is called via `transfer()` or `transferFrom()` and `collect()`. The function `_collect()` can revert in certain circumstances, which means `join()` and `exit()` will also revert. As these functions are meant for composability, this can pose a problem because transactions will not be able to continue.

### Code Snippets

```solidity
contract GClaimManager {
    function join(address adapter, uint48 maturity, uint256 uBal) external {
        ...
        ERC20(claim).safeTransferFrom(msg.sender, address(this), uBal);
        ...
    }

    function exit(address adapter, uint48 maturity, uint256 uBal) external {
        ...
        ERC20(claim).safeTransfer(msg.sender, uBal);
        ...
    }
}

contract Claim is Token {
    function transfer(address to, uint256 value) public override returns (bool) {
        ...
        Divider(divider).collect(msg.sender, adapter, maturity, value, to);
        ...
    }

    function transferFrom(address from, address to, uint256 value) public override returns (bool) {
        ...
        Divider(divider).collect(from, adapter, maturity, value, to);
        ...
    }
}

contract Divider is Trust, ReentrancyGuard, Pausable {
    function collect(...) external nonReentrant onlyClaim(adapter, maturity) whenNotPaused returns (uint256 collected) {
        ...
        return _collect(usr, adapter, maturity, uBal, uBalTransfer > 0 ? uBalTransfer : uBal, to);
        ...
    }

    function _collect(...) internal returns (uint256 collected) {
        ...
        if (_settled(adapter, maturity)) {
            ...
        } else {
            // If we're not settled and we're past maturity + the sponsor window,
            // anyone can settle this Series so revert until someone does
            if (block.timestamp > maturity + SPONSOR_WINDOW) {
                revert(Errors.CollectNotSettled);
                // in some situations revert occurs,
            }
        }
    }
}
```

## Recommendation
Determine the goals for composability and possibly reconsider the revert.

## Note
`GClaimManager` will most likely be deprecated. This issue is included for completeness.

## Medium Risk Report

**Severity:** Medium Risk  
**Context:** `Divider.sol#L331-398`, `Claim.sol#L37-44`

## Situation
In this scenario, assume an actor performs a `transferFrom` transaction on the Claim token contract with a specific `from` address and an amount of 0 tokens. This transaction will succeed in the ERC20 contract as `allowance == 0` and `amount <= allowance`. Then, `collect()` in `Divider.sol` will be called with `uBalTransfer == 0`. 

The `_collect()` function will be invoked where `uBal` and `uBalTransfer` are set to `uBal` (which is the balance of the `from`). This scenario triggers the claim collection from the `from`. The `from` might not want to do the claim collection at that point in time. 

The claim itself will go to the `from`, so nothing is lost there, but the control over timing could be an issue.

```solidity
contract Claim is Token {
    ...
    function transferFrom(...) public override returns (bool) {
        Divider(divider).collect(from, adapter, maturity, value, to);
        return super.transferFrom(from, to, value); // No revert on
        super.transferFrom(from, to, 0); // ,!
    }
}
```

```solidity
contract Divider is Trust, ReentrancyGuard, Pausable {
    ...
    function collect(address usr, address adapter, uint256 maturity, uint256 uBalTransfer, // uBalTransfer == 0 ,!
        address to) external nonReentrant onlyClaim(adapter, maturity)
        whenNotPaused returns (uint256 collected) { 
            uint256 uBal = Claim(msg.sender).balanceOf(usr);
            return _collect(usr, adapter, maturity, uBal, uBalTransfer > 0 ? uBalTransfer : uBal, to); //_collect is called with uBal as second last parameter,!
    } 
}
```

This construction is likely created to support the calling of `collect()` in the `Claim.sol` contract:

```solidity
function collect() external returns (uint256 _collected) {
    return Divider(divider).collect(msg.sender, adapter, maturity, 0, address(0)); // ,!
}
```

## Recommendation
Differentiate between these two calls from the `Claim.sol` contract: `transferFrom()` and `collect()`, and do not trigger a `collect()` from an empty `transferFrom()`.

**Sense:** Fixed in #168.  
**Spearbit:** Acknowledged.

