        if (pool.depositFeeBP > 0) {
            uint depositFee = _amount.mul(pool.depositFeeBP).div(_perMille);
            user.amount = SafeCast.toUint128(user.amount + _amount - depositFee);
        } else {
            user.amount = SafeCast.toUint128(user.amount + _amount);
        }
