    Vault agentOrVault = \_useAgentAsVault ? \_installDefaultAgentApp(\_dao) : \_installVaultApp(\_dao);
    TokenManager tokenManager = \_installTokenManagerApp(\_dao, token, TOKEN\_TRANSFERABLE, TOKEN\_MAX\_PER\_ACCOUNT);
    Finance finance = \_installFinanceApp(\_dao, agentOrVault, \_financePeriod == 0 ? DEFAULT\_FINANCE\_PERIOD : \_financePeriod);

    \_mintTokens(\_acl, tokenManager, \_holders, \_stakes);
